@RestController

public class HelloController {

    private final MeterRegistry meterRegistry;

    // Injeção do MeterRegistry via construtor (o Spring Boot o fornece automaticamente)

    public HelloController(MeterRegistry meterRegistry) {

        this.meterRegistry = meterRegistry;

    }

    @GetMapping("/hello")

    public String hello() {

        // Contador para quantas vezes o endpoint /hello foi chamado

        Counter counter = meterRegistry.counter("app_hello_requests_total");

        counter.increment();

        return "Hello, World!";

    }

    @GetMapping("/slow")

    public String slow() throws InterruptedException {

        // Timer para medir a duração da requisição /slow

        Timer timer = Timer.builder("app_slow_request_duration")

                .description("Duração das requisições /slow em segundos")

                .register(meterRegistry);

        // Medir o tempo de execução simulando uma operação lenta

        return timer.record(() -> {

            try {

                Thread.sleep(3000); // simula demora de 3 segundos

            } catch (InterruptedException e) {

                Thread.currentThread().interrupt();

            }

            return "Slow response";

        });

    }

}
